// services/aiQuestionService.js
// Pure AI-Powered Coding Question Generator using Google Gemini
// All questions are generated by AI — no external platform fetching

const { GoogleGenerativeAI } = require('@google/generative-ai');

// ─────────────────────────────────────────────────────────────────────────────
// Gemini Client (lazy initialisation)
// ─────────────────────────────────────────────────────────────────────────────
let _genAI = null;

const getGeminiClient = () => {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey || apiKey === 'your_gemini_api_key_here') {
    throw new Error('GEMINI_API_KEY is not configured. Please add a real key to backend/.env');
  }
  if (!_genAI) {
    _genAI = new GoogleGenerativeAI(apiKey);
  }
  return _genAI;
};

const isApiKeyConfigured = () => {
  const key = process.env.GEMINI_API_KEY;
  return !!(key && key !== 'your_gemini_api_key_here' && key.length > 10);
};

