// ─────────────────────────────────────────────────────────────────────────────
// Prompt Builder
// ─────────────────────────────────────────────────────────────────────────────
const DIFFICULTY_GUIDANCE = {
  easy: {
    desc: 'straightforward problem requiring ONE simple data structure or algorithm (array traversal, hash map, two-pointer, basic math). O(n) or O(n log n) solution. Suitable for juniors.',
    constraintScale: 'n ≤ 10^5',
    complexityHint: 'O(n) or O(n log n) time, O(n) or O(1) space',
  },
  medium: {
    desc: 'requires combining 2–3 techniques (e.g. binary search + greedy, DP + hashing, sliding window + prefix sum). O(n log n) or O(n²) for small n. Suitable for mid-level engineers.',
    constraintScale: 'n ≤ 10^5',
    complexityHint: 'O(n log n) time, O(n) space',
  },
  hard: {
    desc: 'requires advanced techniques: graph algorithms, segment trees, heavy-light decomposition, advanced DP, mathematical proofs, or amortised analysis. Suitable for senior engineers / competitive programmers.',
    constraintScale: 'n ≤ 2×10^5',
    complexityHint: 'O(n log n) or O(n log² n) time',
  },
};

const buildGeminiPrompt = (topic, difficulty, source, mode, questionIndex) => {
  const profile = PLATFORM_PROFILES[source] || PLATFORM_PROFILES.leetcode;
  const diffGuide = DIFFICULTY_GUIDANCE[difficulty] || DIFFICULTY_GUIDANCE.medium;
  
  // Vary the seed phrasing so consecutive calls generate distinct problems
  const variationHints = [
    `Focus on an array or string manipulation variant.`,
    `Focus on a graph or tree traversal variant.`,
    `Focus on a dynamic programming or memoisation variant.`,
    `Focus on a mathematical or number-theory variant.`,
    `Focus on a sorting and searching variant.`,
    `Focus on a stack, queue, or deque variant.`,
  ];
  const hint = variationHints[questionIndex % variationHints.length];

  const fullModeExtra = mode === 'full'
    ? `,
  "editorial": "3–5 sentence detailed editorial explaining the optimal approach, key insight, and why the naive approach fails",
  "solution_code": "A clean, production-quality Python solution (30–70 lines) with comments explaining each significant step",
  "follow_up": "One natural follow-up question that extends the problem (e.g. handle larger constraints, return all solutions, or solve online/streaming variant)"`
    : '';

  return `You are an elite competitive programming problem setter with 15+ years of experience designing questions for Google, Codeforces, LeetCode, and top university programming courses.

Your task: Generate ONE completely original, mathematically correct, and professionally written coding problem.

=== REQUIREMENTS ===
Platform Style: ${profile.name} — ${profile.style}
I/O Format: ${profile.ioFormat}
Audience: ${profile.audience}
Special Notes: ${profile.extras}

Topic: ${topic}
Difficulty: ${difficulty} — ${diffGuide.desc}
Typical constraints: ${diffGuide.constraintScale}
Expected complexity: ${diffGuide.complexityHint}
Variation focus: ${hint}

=== QUALITY STANDARDS ===
1. The problem MUST be completely original — not a verbatim copy of any known problem
2. All examples must be manually verified correct
3. Provide at least 3 examples (2 standard + 1 edge case)
4. The problem statement must be unambiguous, with every term defined
5. Constraints must be realistic and consistent with the expected complexity
6. Professionally worded — zero grammatical errors, formal tone

=== OUTPUT FORMAT ===
Return ONLY a valid JSON object. No markdown fences, no explanation outside the JSON.

{
  "title": "Concise problem title (4–8 words, title case)",
  "platform": "${source}",
  "difficulty": "${difficulty}",
  "topic": "${topic}",
  "tags": ["tag1", "tag2", "tag3"],
  "time_complexity": "e.g. O(n log n)",
  "space_complexity": "e.g. O(n)",
  "problem_statement": "Full professional problem statement (200–400 words). Define all variables. Use precise mathematical language. ${profile.problemPrefix} ...",
  "input_format": "Precise multi-line description of the complete input format, exactly as a student will read it during the exam (3–6 lines)",
  "output_format": "Precise description of what to output, including edge case behaviour (2–3 lines)",
  "constraints": [
    "1 ≤ n ≤ 10^5",
    "0 ≤ arr[i] ≤ 10^9",
    "All elements are distinct (or whatever applies)",
    "Time limit: 2 seconds",
    "Memory limit: 256 MB"
  ],
  "examples": [
    {
      "input": "exact multi-line input string (use \\n for newlines)",
      "output": "exact output string",
      "explanation": "Step-by-step walkthrough showing exactly how to arrive at the output (3–5 sentences)"
    },
    {
      "input": "second example input",
      "output": "second example output",
      "explanation": "Explanation for second example"
    },
    {
      "input": "edge case input (empty, single element, all same value, etc.)",
      "output": "edge case output",
      "explanation": "Why this edge case produces this output"
    }
  ],
  "test_cases": [
    { "input": "hidden test case 1 input", "output": "expected output", "is_sample": false },
    { "input": "hidden test case 2 input", "output": "expected output", "is_sample": false },
    { "input": "hidden large test case", "output": "expected output", "is_sample": false }
  ],
  "hints": [
    "Hint 1: Think about which data structure allows O(1) average-case lookup...",
    "Hint 2: Consider what happens if you sort the input first...",
    "Hint 3: Try reducing the problem to a simpler subproblem..."
  ],
  "solution_approach": "High-level description of the optimal approach in 3–5 sentences. No code, no pseudocode — explain the intuition and key insight."${fullModeExtra}
}`;
};

// ─────────────────────────────────────────────────────────────────────────────
// JSON Response Parser (handles Gemini markdown fences)
// ─────────────────────────────────────────────────────────────────────────────
const parseGeminiJson = (rawText) => {
  let text = rawText.trim();
  
  // Strip common markdown fences
  text = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();
  
  // Sometimes Gemini wraps in backtick code spans
  if (text.startsWith('`') && text.endsWith('`')) {
    text = text.slice(1, -1).trim();
  }

  // Find the outermost JSON object in case there's surrounding text
  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
    text = text.slice(firstBrace, lastBrace + 1);
  }

  return JSON.parse(text);
};

// ─────────────────────────────────────────────────────────────────────────────
// Structured Question Builder (what gets stored + returned)
// ─────────────────────────────────────────────────────────────────────────────
const buildStructuredQuestion = (parsed, source, difficulty, topic, mode, index) => {
  const profile = PLATFORM_PROFILES[source] || PLATFORM_PROFILES.leetcode;
  
  // Build the "description" field — a beautiful structured text for quick display
  // This uses a consistent format regardless of platform
  const descLines = [];
  
  if (parsed.problem_statement) descLines.push(parsed.problem_statement);
  
  if (parsed.input_format) {
    descLines.push('\n──────────────────');
    descLines.push('📥 Input Format');
    descLines.push('──────────────────');
    descLines.push(parsed.input_format);
  }
  
  if (parsed.output_format) {
    descLines.push('\n📤 Output Format');
    descLines.push('──────────────────');
    descLines.push(parsed.output_format);
  }
  
  if (Array.isArray(parsed.constraints) && parsed.constraints.length > 0) {
    descLines.push('\n📏 Constraints');
    descLines.push('──────────────────');
    parsed.constraints.forEach(c => descLines.push(`• ${c}`));
  }

  const description = descLines.join('\n').trim();

  return {
    id: `ai_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    
    // Core display fields
    title: parsed.title || `${topic} Problem ${index + 1}`,
    platform: source,
    platformName: profile.name,
    difficulty: parsed.difficulty || difficulty,
    topic: parsed.topic || topic,
    tags: Array.isArray(parsed.tags) ? parsed.tags.slice(0, 5) : [topic.toLowerCase()],
    
    // Complexity
    timeComplexity: parsed.time_complexity || 'O(n log n)',
    spaceComplexity: parsed.space_complexity || 'O(n)',
    
    // Rich structured fields (used for proper rendering)
    description,                                               // Quick-view formatted text
    problemStatement:  parsed.problem_statement  || '',
    inputFormat:       parsed.input_format       || '',
    outputFormat:      parsed.output_format      || '',
    constraints:       Array.isArray(parsed.constraints) ? parsed.constraints : [],
    examples:          Array.isArray(parsed.examples)    ? parsed.examples    : [],
    testCases:         Array.isArray(parsed.test_cases)  ? parsed.test_cases  : [],
    hints:             Array.isArray(parsed.hints)        ? parsed.hints       : [],
    solutionApproach:  parsed.solution_approach  || '',
    
    // Full mode extras
    editorial:     parsed.editorial     || null,
    solutionCode:  parsed.solution_code || null,
    followUp:      parsed.follow_up     || null,
    
    // Metadata
    mode,
    generatedAt:  new Date().toISOString(),
    aiGenerated:  true,
    isFallback:   false,
    errorType:    null,
  };
};

