const createFallbackQuestion = (topic, difficulty, source, index, mode) => {
  const diffTemplates = FALLBACK_TEMPLATES[difficulty] || FALLBACK_TEMPLATES.medium;
  const platformTemplates = diffTemplates[source] || diffTemplates.leetcode;
  const parsed = platformTemplates(topic);

  const profile = PLATFORM_PROFILES[source] || PLATFORM_PROFILES.leetcode;

  const descLines = [parsed.problem_statement, ''];
  descLines.push('📥 Input Format\n──────────────────');
  descLines.push(parsed.input_format);
  descLines.push('\n📤 Output Format\n──────────────────');
  descLines.push(parsed.output_format);
  descLines.push('\n📏 Constraints\n──────────────────');
  parsed.constraints.forEach(c => descLines.push(`• ${c}`));

  return {
    id: `fallback_${Date.now()}_${index}`,
    title: parsed.title,
    platform: source,
    platformName: profile.name,
    difficulty,
    topic,
    tags: parsed.tags,
    timeComplexity: parsed.time_complexity,
    spaceComplexity: parsed.space_complexity,
    description: descLines.join('\n').trim(),
    problemStatement: parsed.problem_statement,
    inputFormat: parsed.input_format,
    outputFormat: parsed.output_format,
    constraints: parsed.constraints,
    examples: parsed.examples,
    testCases: parsed.test_cases,
    hints: parsed.hints,
    solutionApproach: parsed.solution_approach,
    editorial: null,
    solutionCode: null,
    followUp: null,
    mode,
    generatedAt: new Date().toISOString(),
    aiGenerated: false,
    isFallback: true,
    errorType: 'AI_KEY_MISSING',
  };
};

// ─────────────────────────────────────────────────────────────────────────────
// Core Generation Function
// ─────────────────────────────────────────────────────────────────────────────
const generateSingleQuestion = async (topic, difficulty, source, mode, model, questionIndex) => {
  const prompt = buildGeminiPrompt(topic, difficulty, source, mode, questionIndex);
  
  const result = await model.generateContent(prompt);
  const rawText = result.response.text();
  
  const parsed = parseGeminiJson(rawText);
  
  // Validate required fields
  if (!parsed.problem_statement || !parsed.examples || parsed.examples.length === 0) {
    throw new Error('AI returned incomplete question data — missing problem_statement or examples');
  }
  
  return buildStructuredQuestion(parsed, source, difficulty, topic, mode, questionIndex);
};

// ─────────────────────────────────────────────────────────────────────────────
// Batch Generation (main export)
// ─────────────────────────────────────────────────────────────────────────────
const generateQuestionBatch = async ({ topic, difficulty, sources, count, mode }) => {
  const results = [];
  const errors = [];
  
  let model = null;
  const apiConfigured = isApiKeyConfigured();
  
  if (apiConfigured) {
    try {
      const genAI = getGeminiClient();
      model = genAI.getGenerativeModel({
        model: 'gemini-1.5-flash',
        generationConfig: {
          temperature: 0.9,       // Higher creativity for varied questions
          topK: 40,
          topP: 0.95,
          maxOutputTokens: mode === 'full' ? 4000 : 2500,
        },
      });
      console.log('✅ Gemini client initialised successfully');
    } catch (err) {
      console.warn('⚠️ Gemini initialisation failed:', err.message);
    }
  } else {
    console.warn('⚠️ GEMINI_API_KEY not configured — using high-quality fallback questions');
  }

  // Distribute questions across sources
  const questionsPerSource = {};
  sources.forEach((src, i) => {
    const base = Math.floor(count / sources.length);
    const extra = i < (count % sources.length) ? 1 : 0;
    questionsPerSource[src] = base + extra;
  });

  let globalIndex = 0;

  for (const source of sources) {
    const countForSource = questionsPerSource[source];
    console.log(`🔄 Generating ${countForSource} ${difficulty} "${topic}" questions from ${source}...`);

    for (let i = 0; i < countForSource; i++) {
      const qIndex = globalIndex++;

      if (!model) {
        // No API key — use rich fallback immediately
        results.push(createFallbackQuestion(topic, difficulty, source, qIndex, mode));
        continue;
      }

      let attempts = 0;
      const maxAttempts = 2;
      let succeeded = false;

      while (attempts < maxAttempts && !succeeded) {
        try {
          attempts++;
          const question = await generateSingleQuestion(topic, difficulty, source, mode, model, qIndex);
          results.push(question);
          succeeded = true;

          // Rate-limit guard between requests
          if (i < countForSource - 1) {
            await new Promise(r => setTimeout(r, 400));
          }
        } catch (err) {
          console.error(`❌ Attempt ${attempts} failed for ${source}[${i}]:`, err.message);
          
          if (attempts >= maxAttempts) {
            let errorType = 'AI_GENERATION_FAILED';
            if (err.message?.includes('quota') || err.message?.includes('rate')) errorType = 'AI_RATE_LIMITED';
            if (err.message?.includes('parse') || err.message?.includes('JSON')) errorType = 'AI_PARSE_ERROR';
            if (err.message?.includes('timeout')) errorType = 'AI_TIMEOUT';
            
            errors.push({ source, index: i, errorType, message: err.message });
            const fallback = createFallbackQuestion(topic, difficulty, source, qIndex, mode);
            fallback.errorType = errorType;
            results.push(fallback);
          } else {
            // Wait before retry
            await new Promise(r => setTimeout(r, 800));
          }
        }
      }
    }
  }

  return {
    questions: results,
    errors,
    apiConfigured,
    meta: {
      requested: count,
      generated: results.length,
      aiGenerated: results.filter(q => q.aiGenerated).length,
      fallbacks: results.filter(q => q.isFallback).length,
      topic,
      difficulty,
      sources,
      mode,
    },
  };
};

module.exports = {
  generateQuestionBatch,
  isApiKeyConfigured,
  PLATFORM_PROFILES,
};
